 }

 .erp-btn--danger {
 border-color: rgb(254 202 202);
 background: white;
 color: rgb(185 28 28);
 }

 .erp-btn--danger:hover {
 background: rgb(254 242 242);
 }

 .erp-badge {
 display: inline-flex;
 min-height: 1.5rem;
 align-items: center;
 gap: .35rem;
 border: 1px solid;
 border-radius: .375rem;
 padding: .15rem .5rem;
 font-size: .7rem;
 font-weight: 600;
 line-height: 1rem;
 white-space: nowrap;
 }

 .erp-badge::before {
 width: .35rem;
 height: .35rem;
 flex: 0 0 .35rem;
 border-radius: 9999px;
 background: currentColor;
 content: "";
 }

 .erp-badge--neutral {
 border-color: rgb(203 213 225);
 background: rgb(241 245 249);
 color: rgb(71 85 105);
 }

 .erp-badge--info {
 border-color: rgb(191 219 254);
 background: rgb(239 246 255);
 color: rgb(29 78 216);
 }

 .erp-badge--success {
 border-color: rgb(187 247 208);
 background: rgb(240 253 244);
 color: rgb(21 128 61);
 }

 .erp-badge--warning {
 border-color: rgb(253 230 138);
 background: rgb(255 251 235);
 color: rgb(180 83 9);
 }

 .erp-badge--danger {
 border-color: rgb(254 202 202);
 background: rgb(254 242 242);
 color: rgb(185 28 28);
 }

 .erp-panel-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 1rem;
 border-bottom: 1px solid var(--erp-border);
 padding: .875rem 1rem;
 }

 .erp-table-wrap {
 width: 100%;
 overflow-x: auto;
 overscroll-behavior-inline: contain;
 }

 .erp-scrollbar {
 scrollbar-width: thin;
 scrollbar-color: rgb(71 85 105) transparent;
 }

 .erp-skip-link {
 position: fixed;
 top: .5rem;
 right: .5rem;
 z-index: 100;
 transform: translateY(-150%);
 border-radius: .5rem;
 background: rgb(37 99 235);
 padding: .65rem 1rem;
 color: white;
 font-size: .75rem;
 font-weight: 700;
 transition: transform .15s ease;
 }

 .erp-skip-link:focus {
 transform: translateY(0);
 }

 .erp-nav {
 display: flex;
 flex-direction: column;
 gap: .25rem;
 }

 .erp-nav-link {
 position: relative;
 display: flex;
 min-height: 2.5rem;
 align-items: center;
 gap: .7rem;
 border-radius: .55rem;
 padding: .55rem .7rem;
 color: rgb(203 213 225);
 font-size: .78rem;
 font-weight: 500;
 transition: color .15s ease, background-color .15s ease, transform .15s ease;
 }

 .erp-nav-link:hover {
 background: rgb(255 255 255 / .08);
 color: white;
 }

 .erp-nav-link.is-active {
 background: rgb(29 78 216);
 color: white;
 font-weight: 600;
 box-shadow: 0 6px 16px rgb(2 6 23 / .22);
 }

 .erp-nav-link.is-active::after {
 position: absolute;
 inset-block: .55rem;
 right: -.75rem;
 width: 3px;
 border-radius: 99px 0 0 99px;
 background: rgb(147 197 253);
 content: "";
 }

 .erp-nav-link.is-unavailable {
 cursor: default;
 color: rgb(100 116 139);
 }

 .erp-nav-link>svg {
 width: 1.1rem;
 height: 1.1rem;
 flex: 0 0 1.1rem;
 fill: none;
 stroke: currentColor;
 stroke-linecap: round;
 stroke-linejoin: round;
 stroke-width: 1.7;
 }

 .erp-nav-group {
 margin-top: .35rem;
 border-top: 1px solid rgb(255 255 255 / .055);
 padding-top: .35rem;
 }

 .erp-nav-group>summary {
 display: flex;
 min-height: 1.9rem;
 cursor: pointer;
 list-style: none;
 align-items: center;
 justify-content: space-between;
 padding: .25rem .7rem;
 color: rgb(148 163 184);
 font-size: .64rem;
 font-weight: 600;
 letter-spacing: .025em;
 }

 .erp-nav-group>summary::-webkit-details-marker {
 display: none;
 }

 .erp-nav-group>summary svg {
 width: .9rem;
 height: .9rem;
 fill: none;
 stroke: currentColor;
 stroke-width: 1.8;
 transition: transform .15s ease;
 }

 .erp-nav-group:not([open])>summary svg {
 transform: rotate(90deg);
 }

 .erp-nav-group>summary:hover {
 color: rgb(226 232 240);
 }

 .erp-nav-group__items {
 display: grid;
 gap: .1rem;
